import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:flutter/material.dart';
class BelanjakuOrderHistoryScreen extends StatelessWidget { const BelanjakuOrderHistoryScreen({super.key}); @override Widget build(BuildContext context) { final user = FirebaseAuth.instance.currentUser; return Scaffold(appBar: AppBar(title: const Text('Pesanan Saya')), body: user == null ? const Center(child: Text('Silakan masuk ke DesaPay.')) : StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(stream: FirebaseFirestore.instance.collection('belanjaku_orders').where('uid', isEqualTo: user.uid).snapshots(), builder: (context, snap) { if (snap.hasError) return const Center(child: Text('Riwayat pesanan belum dapat dimuat.')); if (!snap.hasData) return const Center(child: CircularProgressIndicator()); final docs = snap.data!.docs; if (docs.isEmpty) return const Center(child: Text('Belum ada pesanan Belanjaku.')); return ListView.builder(itemCount: docs.length, itemBuilder: (context, i) { final d = docs[i].data(); return ListTile(leading: const Icon(Icons.receipt_long, color: Color(0xFF0866D9)), title: Text('Pesanan #' + docs[i].id), subtitle: Text((d['status'] as String? ?? 'Menunggu') + ' • ' + (d['itemCount']?.toString() ?? '0') + ' item'), trailing: Text('Rp ' + (d['total']?.toString() ?? '0'))); }); })); } }
